targets.expr:
(
  sum by (service_basename) (
    label_replace(
      rate(istio_requests_total{
        reporter="destination",
        request_path!~"probe|metadata|blocked|other|/metrics|/|/events|.*/readyz|.*/livez|.*/healthz|.*/openapi.*|.*/docs|.*/clear_cache.*|/wait-for-drain",
        response_code!~"[45].*",
        grpc_response_status!~"[1-9].+"
      }[$__rate_interval]),
      "service_basename", "$1", "destination_service", "([a-z-]*[a-z]).*"
    )
  ) 
  / 
  sum by (service_basename) (
    label_replace(
      rate(istio_requests_total{
        reporter="destination",
        request_path!~"probe|metadata|blocked|other|/metrics|/|/events|.*/readyz|.*/livez|.*/healthz|.*/openapi.*|.*/docs|.*/clear_cache.*|/wait-for-drain"
      }[$__rate_interval]),
      "service_basename", "$1", "destination_service", "([a-z-]*[a-z]).*"
    )
  )
) * 100
